const item = $input.first().json;
const catId = Number(item.glpi_category_id);
const dados = typeof item.dados_solicitacao === 'string'
  ? JSON.parse(item.dados_solicitacao)
  : item.dados_solicitacao;

if (!dados) throw new Error('dados_solicitacao está vazio para o chamado #' + item.glpi_ticket_id);

// Mapear categoria → ação do PowerShell
const mapa = {
  15: 'Criar',
  16: 'Reset',       // Reset de senha
  17: 'Reativar',
  18: 'Desativar',
  20: 'CriarEmail',
  22: 'Transferir'
};

const acao = mapa[catId];
if (!acao) throw new Error('Categoria ' + catId + ' não é uma operação de AD (esperado 15-18, 20 ou 22).');

// Codificar dados em Base64 — evita problemas de escape com aspas, acentos
// e shells diferentes (cmd.exe vs PowerShell) no servidor SSH.
const dadosJson = JSON.stringify(dados);
const dadosB64 = Buffer.from(dadosJson, 'utf8').toString('base64');

return [{ json: {
  acao,
  categoria: catId,
  ticket_id: item.glpi_ticket_id,
  conversa_id: item.conversa_id,
  dados_json: dadosJson,
  comando: 'powershell.exe -ExecutionPolicy Bypass -File "C:\\Scripts\\Executar_AD_Automatico.ps1" -Acao "' + acao + '" -DadosB64 "' + dadosB64 + '"'
}}];

const inJson = $input.first().json;
const stdout = inJson.stdout || '';
const stderr = inJson.stderr || '';
const sshError = inJson.error || inJson.errorMessage;
const ticketId = $('Montar Comando AD').item.json.ticket_id;
const conversaId = $('Montar Comando AD').item.json.conversa_id;
const acao = $('Montar Comando AD').item.json.acao;
const token = $('Trigger').item.json.access_token;

let resultado;
if (sshError && !stdout) {
  // Falha de conexão/execução SSH antes mesmo do PowerShell rodar
  resultado = { sucesso: false, erro: 'Falha SSH no servidor AD: ' + sshError };
} else if (!stdout.trim()) {
  resultado = { sucesso: false, erro: 'Servidor AD não retornou saída. stderr: ' + (stderr || 'vazio') };
} else {
  // Extrai o ULTIMO objeto JSON valido do stdout (defensivo: PowerShell as vezes imprime tabela do cmdlet antes do JSON)
  resultado = null;
  let lastErr = null;
  // 1) Tenta achar o ultimo { ... } completo no stdout
  const candidatos = stdout.match(/\{[\s\S]*?\}\s*$/);
  if (candidatos) {
    try { resultado = JSON.parse(candidatos[0]); } catch(e) { lastErr = e.message; }
  }
  // 2) Fallback: tenta parse direto do trim
  if (!resultado) {
    try { resultado = JSON.parse(stdout.trim()); } catch(e) { lastErr = e.message; }
  }
  // 3) Fallback final: tenta pegar JSON da ultima linha
  if (!resultado) {
    const linhas = stdout.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    for (let i = linhas.length - 1; i >= 0; i--) {
      const l = linhas[i];
      if (l.startsWith('{') && l.endsWith('}')) {
        try { resultado = JSON.parse(l); break; } catch(_) {}
      }
    }
  }
  if (!resultado) {
    resultado = { sucesso: false, erro: 'Saída inválida do PowerShell (sem JSON válido): ' + stdout.substring(stdout.length - 300) };
  }
}

// Montar mensagem para o usuário via WhatsApp
let mensagemUsuario = '';
const acaoReal = resultado.acao_real || '';

if (resultado.sucesso) {
  switch(acaoReal || acao) {
    case 'criado':
    case 'reativado':
    case 'atualizado':
      mensagemUsuario = '\u2705 *Chamado #' + ticketId + ' — ' + (acaoReal === 'atualizado' ? 'Conta Atualizada' : acaoReal === 'reativado' ? 'Conta Reativada' : 'Executado') + '*\n\n' +
        (acaoReal === 'atualizado' ? 'Usuário já existia ativo no AD. Dados e perfil de referência foram atualizados e a senha foi redefinida' : acaoReal === 'reativado' ? 'Usuário reativado (existia desativado)' : 'Usuário criado') + ' com sucesso!\n' +
        '*Login:* ' + resultado.login + '\n' +
        '*Senha provisória:* ' + resultado.senha + '\n' +
        '*Domínio:* ' + (resultado.dominio || 'pma.local') + '\n\n' +
        '_A senha deve ser alterada no primeiro acesso._';
      break;
    case 'reset_senha':
      mensagemUsuario = '\u2705 *Chamado #' + ticketId + ' — Senha Resetada*\n\n' +
        '*Login:* ' + resultado.login + '\n' +
        '*Nova senha:* ' + resultado.senha + '\n' +
        '*Domínio:* ' + (resultado.dominio || 'pma.local') + '\n\n' +
        '_A senha deve ser alterada no primeiro acesso._';
      break;
    case 'desativado':
    case 'ja_desativado':
      mensagemUsuario = '\u2705 *Chamado #' + ticketId + ' — Usuário Desativado*\n\n' +
        'O usuário *' + resultado.login + '* foi desativado com sucesso.';
      break;
    case 'acesso_pasta':
      mensagemUsuario = '\u2705 *Chamado #' + ticketId + ' — Acesso Concedido*\n\n' +
        'Acesso à pasta *' + resultado.pasta + '* concedido para *' + resultado.login + '*.';
      break;
    case 'transferido':
      mensagemUsuario = '\u2705 *Chamado #' + ticketId + ' — Transferência Concluída*\n\n' +
        'Usuário transferido com sucesso!\n' +
        '*Login:* ' + resultado.login + '\n' +
        '*Nova senha:* ' + resultado.senha + '\n' +
        '*Domínio:* ' + (resultado.dominio || 'pma.local') + '\n' +
        '*Novo setor:* ' + (resultado.novo_setor || '') + '\n' +
        '*Novo local:* ' + (resultado.novo_local || '') + '\n\n' +
        '_A senha deve ser alterada no primeiro acesso._';
      break;
    case 'email_criado':
      mensagemUsuario = '\u2705 *Chamado #' + ticketId + ' — E-mail Institucional Criado*\n\n' +
        'E-mail criado com sucesso!\n' +
        '*Login:* ' + resultado.login + '\n' +
        '*E-mail:* ' + resultado.email + '\n' +
        '*Banco de Dados:* ' + (resultado.database || 'Small Database') + '\n\n' +
        '_O e-mail já está disponível para uso._';
      break;
    default:
      mensagemUsuario = '\u2705 *Chamado #' + ticketId + ' — Concluído*\n\n' + (resultado.mensagem || '');
  }
} else {
  // Tratar casos especiais de erro com mensagens amigáveis
  switch(acaoReal) {
    case 'usuario_ja_existe':
      mensagemUsuario = '\u26A0\uFE0F *Chamado #' + ticketId + ' — Usuário Já Existe*\n\n' +
        'O usuário *' + resultado.login + '* já existe e está *ATIVO* no AD com o nome *' + resultado.nome_existente + '*.\n\n' +
        '\u{1F4C5} Último acesso com sucesso: *' + (resultado.ultimo_logon || 'Não disponível') + '*\n\n' +
        '\u{1F4A1} Recomendamos abrir um novo chamado solicitando *Reset de Senha* (menu 1.2).';
      break;
    case 'possivel_mesmo_usuario':
      mensagemUsuario = '\u26A0\uFE0F *Chamado #' + ticketId + ' — Possível Mudança de Nome*\n\n' +
        'O login *' + resultado.login + '* já existe no AD com o nome *' + resultado.nome_existente + '*.\n' +
        'O nome solicitado é *' + resultado.nome_solicitado + '*.\n\n' +
        '\u{1F4C5} Último acesso: *' + (resultado.ultimo_logon || 'Não disponível') + '*\n\n' +
        'Isso pode indicar mudança de sobrenome (casamento ou divórcio).\n' +
        'Por favor, confirme com o solicitante se é a mesma pessoa.\n\n' +
        '\u{1F4A1} Se for a mesma pessoa, solicite *Transferência de Setor* (menu 1.7) ou contate a equipe de TI para atualizar o nome na conta existente.';
      break;
    case 'usuario_nao_encontrado': {
      const sug = Array.isArray(resultado.sugestoes) ? resultado.sugestoes : [];
      const listaSug = sug.length
        ? sug.map(s => '  • *' + s.login + '* — ' + (s.nome || '') + (s.ativo === false ? ' _(desativado)_' : '')).join('\n')
        : '  _(nenhuma sugestão encontrada)_';
      mensagemUsuario = '\u26A0\uFE0F *Chamado #' + ticketId + ' — Login não localizado*\n\n' +
        'O login *' + (resultado.login_informado || '') + '* informado não foi encontrado no Active Directory.\n\n' +
        '\u{1F50D} *Sugestões de logins parecidos:*\n' + listaSug + '\n\n' +
        '\u{1F4A1} Verifique se o login foi digitado corretamente e abra um novo chamado com o login correto.';
      break;
    }
    case 'perfil_referencia_nao_encontrado': {
      const sug = Array.isArray(resultado.sugestoes) ? resultado.sugestoes : [];
      const listaSug = sug.length
        ? sug.map(s => '  • *' + s.login + '* — ' + (s.nome || '') + (s.ativo === false ? ' _(desativado)_' : '')).join('\n')
        : '  _(nenhuma sugestão encontrada)_';
      mensagemUsuario = '\u26A0\uFE0F *Chamado #' + ticketId + ' — Perfil de referência não localizado*\n\n' +
        'O perfil de referência *' + (resultado.perfil_informado || '') + '* informado não foi encontrado no Active Directory.\n\n' +
        '\u{1F50D} *Sugestões de perfis parecidos:*\n' + listaSug + '\n\n' +
        '\u{1F4A1} O perfil de referência deve ser o login de um colega que já possua os acessos desejados. Abra um novo chamado informando o login correto.';
      break;
    }
    default:
      mensagemUsuario = '\u26A0\uFE0F *Chamado #' + ticketId + ' — Erro na Execução*\n\n' +
        'Ocorreu um erro ao processar sua solicitação. A equipe técnica foi notificada.\n\n' +
        '_Detalhes técnicos foram registrados no chamado._';
  }
}

// Montar followup para o GLPI (sempre inclui detalhes técnicos)
let followupHtml = '';
if (resultado.sucesso) {
  followupHtml = '<p><strong>[AUTOMÁTICO] Operação AD executada com sucesso</strong></p>' +
    '<p>Ação: ' + (acaoReal || acao) + '</p>' +
    '<p>Login: ' + (resultado.login || 'N/A') + '</p>' +
    (resultado.ou ? '<p>OU: ' + resultado.ou + '</p>' : '') +
    (resultado.pasta ? '<p>Pasta: ' + resultado.pasta + '</p>' : '') +
    '<p>' + (resultado.mensagem || '') + '</p>';
} else {
  followupHtml = '<p><strong>[AUTOMÁTICO] ERRO na execução AD</strong></p>' +
    '<p>Ação real: ' + (acaoReal || 'N/A') + '</p>' +
    '<p>' + (resultado.erro || stderr || 'Erro desconhecido') + '</p>' +
    (resultado.login ? '<p>Login: ' + resultado.login + '</p>' : '') +
    (resultado.nome_existente ? '<p>Nome existente: ' + resultado.nome_existente + '</p>' : '') +
    (resultado.nome_solicitado ? '<p>Nome solicitado: ' + resultado.nome_solicitado + '</p>' : '') +
    (resultado.ultimo_logon ? '<p>Último logon: ' + resultado.ultimo_logon + '</p>' : '') +
    '<p>' + (resultado.mensagem || '') + '</p>';
}

// Converter formatação WhatsApp markdown → HTML para registro no GLPI
const mensagemUsuarioHtml = '<p>' + mensagemUsuario
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\*([^*\n]+)\*/g, '<strong>$1</strong>')
  .replace(/_([^_\n]+)_/g, '<em>$1</em>')
  .replace(/\n/g, '<br>') + '</p>';

return [{ json: {
  sucesso: resultado.sucesso,
  resultado: resultado,
  ticket_id: ticketId,
  conversa_id: conversaId,
  token: token,
  mensagem_usuario: mensagemUsuario,
  mensagem_usuario_html: mensagemUsuarioHtml,
  followup_html: followupHtml,
  resultado_json: JSON.stringify(resultado)
}}];
